import{_ as a,o as t,c as p,a3 as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/60-这种魔力从何而来？.md","filePath":"books/attached/60-这种魔力从何而来？.md","lastUpdated":1794316978000}'),_={name:"books/attached/60-这种魔力从何而来？.md"};function r(s,e,n,d,i,c){return t(),p("div",null,[...e[0]||(e[0]=[o('<h3 id="这种魔力从何而来" tabindex="-1">这种魔力从何而来？ <a class="header-anchor" href="#这种魔力从何而来" aria-label="Permalink to &quot;这种魔力从何而来？&quot;">​</a></h3><p>安全型依恋风格人群这种优良特质，到底是天生的还是后天习得呢？约翰·鲍尔比认为，依恋风格是生活经历使然，特别体现在早年与父母的交流上。如果父母对于孩子提出的需求非常敏锐并且积极回应，那么孩子就更可能发展成为安全型依恋风格。这样的孩子在成长过程中，深知自己是可以依靠父母的，也深知自己的父母总会在需要的时候在他身边。鲍尔比还认为，这种特质会从孩童时期一直延续到成人，进而影响到成年以后与伴侣的亲密关系。</p><p>那么，有什么证据来证明这些猜想呢？2000年，莱斯利·阿特金森（Leslie Atkinson）在多伦多的瑞尔森大学进行了一项儿童发展研究。这项研究与其他同时合作完成，基于41项前期研究进行了元分析（也就是后续的荟萃研究）。整个研究对于两千多对亲子组合进行了分析，以此对家长敏感性与孩子依恋风格之间的联系进行评估。研究结果显示，家长的敏感性与孩子的依恋风格之间呈现显著的弱相关关系。也就是说，母亲越敏锐，她的孩子越倾向于发展出安全型的依恋风格。而弱相关性则表示，从方法学的视角来看，可能还会有其他因素也在影响着孩子的依恋风格。除此之外，父母温和的脾气也比较容易让孩子形成安全型依恋风格，因为随和个性的父母会对孩子进行更多的回应。同时，父母的积极心理状态，包括婚姻的满意度高，压力和焦虑程度低，以及足够的社会支持也是重要的因素。最后，父母陪伴关照孩子的时长较多的话，孩子也更容易形成安全型依恋风格。</p><p>为了更深入探讨这个问题，我们近年来渐渐开始认可另一种观点，那就是依恋风格是基因决定的。在一项与遗传相关的研究中发现，特定的依恋风格很大程度上，由基因的特定变异体决定。来自堪萨斯大学的奥米尔·吉拉斯（Omir Gillath）以及他来自加州大学戴维斯分校的同事在这项研究中发现，有一种多巴胺受体D2型基因的变异体，与焦虑型依恋风格的形成有关；5羟色胺1A受体的变异体与回避性依恋风格有关。已有研究表明，这两种基因在许多的大脑功能中，都扮演了很重要的角色，包括情绪和奖励、注意等行为，更重要的是在社交行为与恋爱关系中也产生着很大的影响。本书的作者认为：“特定的基因可以在一定程度上解释依恋中的不安全感，不过个体之间各式各样的差异，还需要由其他的基因以及相关社会经历来解释。”换句话来说，基因的确很大程度上决定了我们的依恋风格。</p><p>不过，倘若我们幼儿时期形成了安全型依恋风格，它就一定会延续到成年时期吗？为了验证这个问题，依恋理论的研究者们重访了一些二十世纪七八十年代的幼儿被试，这些人已经二十多岁了。那么，这些在婴幼儿时期被划分为安全型依恋风格的人，是否将依恋风格保持到了成人阶段呢？问题的答案至今扑朔迷离。有三项研究都并没有发现，人们婴幼儿期和成人阶段依恋风格有什么关联，而另两项研究却发现，婴幼儿期与成人期的依恋风格，有着数理统计上的显著相关。我们只能说，婴幼儿时期的依恋风格与成人时期或许有比较弱的相关性。</p><p>那么，安全型依恋风格到底从何而来呢？随着越来越多研究者的关注，有越来越多的证据表明，安全型依恋风格的形成，并不是由单一因素导致的。而父母悉心照料、敏锐回应就更容易教养出安全型依恋风格孩子的说法，有些太过片面了。相反，形成这种依恋风格模式的因素，是一个互相关联的整体，其中包括：生命的早期与父母的关系、遗传基因，当然还包括成人以后的恋爱经历等等其他因素。一般来说，有70%到75%的人，成年之后保持了早期的依恋风格，而剩下的25%到30%的人，则报告称他们的依恋风格有所变化。</p><p>研究者认为，这种依恋风格的转变多半归因于成年以后的恋爱经历。这些恋爱经历的作用非常强大，甚至会颠覆人们对于亲密关系的信念与态度。当然，这种变化是双向的——安全型依恋风格的人可能会逐渐丧失安全感，原本不安全的人也可能渐渐建立起安全感来。对于非安全型的人们来说，这倒是个获得幸福亲密关系的重大利好消息。而对于安全型的人来说，这项发现可能就要引起警觉，因为安全感的丧失，会令人失去良多。</p><p>探秘安全型思维模式——为你的伴侣建立安全基地</p><p>细细想来，安全型依恋风格的人，在伴侣生命中所扮演的最重要角色，就是为之提供一个安全港湾——为伴侣提供一个宽松的条件，鼓励他们追逐自己的喜好，带着满满的自信迎接世界的挑战。卡耐基梅隆大学的布鲁克·菲尼（Brooke Feeney）与罗格仙妮·思拉什（Roxanne Thrush）在2010年刊布了一项研究结果，表示有三种典型的行为，会摧毁这种安全型依恋风格建造的安全基地。当然，你完全可以照着下面三种安全型行为来做，从而为伴侣建立起安全基地。</p><p>-积极回应：对于对方的焦虑不安表示积极地回应；如果对方很需要你，一定要给他们一个依靠的肩膀；无微不至地关怀对方，及时表示安慰。</p><p>-不要过多干预：为对方的努力提供幕后支撑；在帮助他们的时候一定要掌握方法，让对方感觉自己并不是无能的。放手让对方做自己想做的事情，而非一直力求掌控局面、事无巨细地干预对方，打击他们的自信心和效能感。</p><p>-及时鼓励：对于对方设立的学习与自我目标，及时表示鼓励与接纳，以此建立起他们的高度自尊。</p>',12)])])}const m=a(_,[["render",r]]);export{h as __pageData,m as default};
